@Suite("Modes: splitAttackTiles") struct ModesSplitAttackTiles {
    @Test("hands a lone rival the whole attack")
    func handsALoneRivalTheWholeAttack() {
        #expect(splitAttackTiles(count: 4, targets: 1) == [4])
        #expect(splitAttackTiles(count: 1, targets: 1) == [1])
    }

    @Test("splits evenly when the attack divides")
    func splitsEvenlyWhenTheAttackDivides() {
        #expect(splitAttackTiles(count: 6, targets: 3) == [2, 2, 2])
        #expect(splitAttackTiles(count: 7, targets: 7) == [1, 1, 1, 1, 1, 1, 1])
    }

    @Test("always sums to the attack — a single tile still lands somewhere")
    func alwaysSumsToTheAttack() {
        for count in 0...12 {
            for targets in 1...7 {
                let shares = splitAttackTiles(count: Double(count), targets: targets)
                #expect(shares.count == targets)
                #expect(shares.reduce(0, +) == count)
            }
        }
    }

    @Test("lands the remainder from the given seat, wrapping round")
    func landsTheRemainderFromTheGivenSeatWrappingRound() {
        #expect(splitAttackTiles(count: 5, targets: 3, from: 0) == [2, 2, 1])
        #expect(splitAttackTiles(count: 5, targets: 3, from: 1) == [1, 2, 2])
        #expect(splitAttackTiles(count: 5, targets: 3, from: 2) == [2, 1, 2])
        // The rotation is a courtesy, not a requirement — any offset still sums.
        #expect(splitAttackTiles(count: 5, targets: 3, from: 7) == [1, 2, 2])
        #expect(splitAttackTiles(count: 5, targets: 3, from: -1) == [2, 1, 2])
    }

    @Test("never scales the total up with the size of the room")
    func neverScalesTheTotalUpWithTheSizeOfTheRoom() {
        // Eight players: seven targets take, between them, exactly what one
        // rival would — the room makes each hit smaller, not the game harder.
        let attack = battleAttackTiles(wordLength: 8, round: 3) // a big final-round word
        let shares = splitAttackTiles(count: Double(attack), targets: 7)
        #expect(shares.reduce(0, +) == attack)
        let ceiling = Int((Double(attack) / 7).rounded(.up))
        for share in shares { #expect(share <= ceiling) }
    }

    @Test("shrugs off nonsense")
    func shrugsOffNonsense() {
        #expect(splitAttackTiles(count: 5, targets: 0) == [])
        #expect(splitAttackTiles(count: -3, targets: 4) == [0, 0, 0, 0])
        #expect(splitAttackTiles(count: Double.nan, targets: 4) == [])
    }
}

@Suite("Modes: formatSeconds") struct ModesFormatSeconds {
    @Test("formats whole minutes")
    func formatsWholeMinutes() {
        #expect(formatSeconds(180) == "3:00")
        #expect(formatSeconds(60) == "1:00")
    }

    @Test("pads seconds to two digits")
    func padsSecondsToTwoDigits() {
        #expect(formatSeconds(75) == "1:15")
        #expect(formatSeconds(9) == "0:09")
    }

    @Test("clamps at zero")
    func clampsAtZero() {
        #expect(formatSeconds(0) == "0:00")
        #expect(formatSeconds(-3) == "0:00")
    }
}

// MARK: - Fixture parity

private struct ModesFixture: Decodable {
    struct AttackCase: Decodable {
        let len: Int
        let round: Int
        let grewFrom: [Int]
        let result: Int
    }
    struct SplitCase: Decodable {
        let count: Double
        let targets: Int
        let from: Int
        let shares: [Int]
    }
    struct PacingCase: Decodable {
        let pace: String
        let interval: Int
        let seconds: Int
        let tiles: Int
    }
    struct RoundCase: Decodable {
        let seconds: Double
        let round: Int
    }
    struct DripCase: Decodable {
        let index: Int
        let tiles: Int
    }
    struct InitialSeconds: Decodable {
        let regular: Int
        let fast: Int
    }

    let attack: [AttackCase]
    let split: [SplitCase]
    let pacing: [PacingCase]
    let rounds: [RoundCase]
    let drips: [DripCase]
    let initialSeconds: InitialSeconds
}

@Suite("Modes fixture parity") struct ModesFixtureParity {
    fileprivate let fx: ModesFixture = loadFixture("modes")

    @Test func attackMatchesJsTables() {
        #expect(fx.attack.count > 0)
        for c in fx.attack {
            #expect(
                battleAttackTiles(wordLength: c.len, round: c.round, grewFrom: c.grewFrom) == c.result,
                "len \(c.len) round \(c.round) grewFrom \(c.grewFrom)"
            )
        }
    }

    @Test func splitMatchesJsTables() {
        #expect(fx.split.count > 0)
        for c in fx.split {
            #expect(
                splitAttackTiles(count: c.count, targets: c.targets, from: c.from) == c.shares,
                "count \(c.count) targets \(c.targets) from \(c.from)"
            )
        }
    }

    @Test func pacingMatchesJsTables() throws {
        #expect(fx.pacing.count > 0)
        for c in fx.pacing {
            let pace = try #require(SoloPace(rawValue: c.pace))
            #expect(endlessDripSeconds(c.interval, pace) == c.seconds, "seconds at \(c.pace) interval \(c.interval)")
            #expect(endlessDripTiles(c.interval, pace) == c.tiles, "tiles at \(c.pace) interval \(c.interval)")
        }
    }

    @Test func roundsMatchJsTables() {
        #expect(fx.rounds.count > 0)
        for c in fx.rounds {
            #expect(battleRoundAt(seconds: c.seconds) == c.round, "round at \(c.seconds)s")
        }
    }

    @Test func dripsMatchJsTables() {
        #expect(fx.drips.count > 0)
        for c in fx.drips {
            #expect(battleDripTilesAt(dripIndex: c.index) == c.tiles, "drip \(c.index)")
        }
    }

    @Test func initialSecondsMatchJsTables() {
        #expect(endlessInitialSeconds(.regular) == fx.initialSeconds.regular)
        #expect(endlessInitialSeconds(.fast) == fx.initialSeconds.fast)
    }
}
